"""
Customer-facing company facts for the shop assistant. Deliberately a small,
hand-written, PUBLIC fact sheet - the assistant for shoppers never touches
the internal documents the CEO assistant is grounded in. Policies here are
demo policies for a portfolio project (no real orders ship).
"""
COMPANY = {
    "name": "Loomwell",
    "about": (
        "Loomwell is a small label that pairs a linen shirt line with T-shirts and hoodies printed "
        "with artwork researched and generated by AI design agents and approved by a human before "
        "anything goes on sale."
    ),
}

FAQ = [
    (("ship", "delivery", "deliver", "arrive", "how long"),
     "Delivery is 3-5 working days across India. Orders under ₹999 pay a flat ₹59 delivery fee; orders of ₹999 and above ship free."),
    (("return", "refund", "exchange", "replace"),
     "You can return unworn items within 7 days of delivery for an exchange or refund. Custom-printed pieces are only returnable if they arrive damaged or misprinted."),
    (("size", "fit", "sizing", "measurement"),
     "We stock S, M, L and XL. T-shirts and hoodies run true to size with a relaxed cut; linen shirts are cut loose - size down if you prefer a closer fit."),
    (("wash", "care", "shrink", "iron"),
     "Cotton tees: machine wash cold, inside out, tumble dry low. Linen: gentle cycle or hand wash, line dry, and don't over-iron - the creases are part of it."),
    (("pay", "payment", "upi", "card", "cod", "cash"),
     "Checkout lets you choose UPI, card, net banking, wallets or pay on delivery. This is a portfolio demo, so no real payment is ever taken."),
    (("custom", "print your own", "own design", "personal"),
     "Use Print your own (in the top menu): upload artwork or describe it for the AI to draw, pick a T-shirt/hoodie/full-sleeve and a colour, preview it, then order it for ₹999."),
    (("who", "about", "company", "brand", "made"),
     COMPANY["about"]),
    (("contact", "support", "help", "human", "agent"),
     "Tell me what's wrong and I'll open a support ticket for the team - or type 'talk to support'."),
    (("fabric", "material", "cotton", "linen"),
     "The linen shirts are washed linen with a natural, slightly rumpled texture. The tees and hoodies are cotton-rich with a soft hand feel that holds a print well."),
]


def answer_faq(text: str) -> str | None:
    t = text.lower()
    for keys, answer in FAQ:
        if any(k in t for k in keys):
            return answer
    return None
